package com.hermes.jarvis.web;
import android.content.*;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import java.io.*;import java.net.URL;import okhttp3.*;
public final class ImageDownloadUtil{
 private ImageDownloadUtil(){}
 public static void download(Context c,String url,String title){new Thread(()->{try{OkHttpClient client=new OkHttpClient();Request r=new Request.Builder().url(url).get().build();try(Response resp=client.newCall(r).execute()){if(!resp.isSuccessful()||resp.body()==null)throw new IOException("HTTP "+resp.code());String name="JARVIS_"+System.currentTimeMillis()+".jpg";if(Build.VERSION.SDK_INT>=29){ContentResolver cr=c.getContentResolver();ContentValues v=new ContentValues();v.put(MediaStore.Downloads.DISPLAY_NAME,name);v.put(MediaStore.Downloads.MIME_TYPE,"image/jpeg");v.put(MediaStore.Downloads.RELATIVE_PATH,Environment.DIRECTORY_DOWNLOADS+"/JARVIS");v.put(MediaStore.Downloads.IS_PENDING,1);Uri u=cr.insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,v);if(u==null)throw new IOException("Gagal membuat file");try(InputStream in=resp.body().byteStream();OutputStream out=cr.openOutputStream(u)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}v.clear();v.put(MediaStore.Downloads.IS_PENDING,0);cr.update(u,v,null,null);}else{File dir=Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS+"/JARVIS");if(!dir.exists()&&!dir.mkdirs())throw new IOException("Gagal membuat folder");File f=new File(dir,name);try(InputStream in=resp.body().byteStream();OutputStream out=new FileOutputStream(f)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}android.media.MediaScannerConnection.scanFile(c,new String[]{f.getAbsolutePath()},new String[]{"image/jpeg"},null);}}
 MainThread.toast(c,"✅ Gambar disimpan di Download/JARVIS");}catch(Exception e){MainThread.toast(c,"❌ Download gagal: "+e.getMessage());}}).start();}
 static final class MainThread{static void toast(Context c,String s){new Handler(Looper.getMainLooper()).post(()->android.widget.Toast.makeText(c,s,android.widget.Toast.LENGTH_LONG).show());}}
}
